quests[24687] = { id = 24687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bouquets of Death", description = "You're already familiar with the first phase of the Bloodpetals' life cycle: the waterborne seed.  The next phase, however, is not so docile: the pack of juveniles.\n\nWhen Bloodpetals hatch, they quickly form gangs and travel together, offsetting their weakness with overwhelming numbers.  These packs of young lashers normally keep to themselves, but upset one of them and you upset them all.\n\nFor our safety and the safety of others, dispose of them.  They roam close by, to the west and north.", sourceObjective = "Kill 6 packs of Juvenile Lashers.", completion = "You return victorious.  Good, good... perhaps the crater will now be a bit safer to those who travel through it.", sourceObjectiveStatus = "unverified-source-field" }
quests[24688] = { id = 24688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zen'Aliri", description = "You've already met one of my new students, the young worgen named Garl.  My other student is a troll by the name of Zen'Aliri.  He currently camps with the explorers of Marshal's Expedition, to the west of here.\n\nTake these results to him, {name}, and tell him to read them well.", sourceObjective = "Report to Zen'Aliri in Marshal's Stand.", sourceObjectiveStatus = "unverified-source-field" }
quests[24689] = { id = 24689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flowing to the North", description = "Ithis Moonwarden is the night elf druid who indoctrinated me into the Cenarion Circle.  He has set up camp north of here, near the cliffs of the crater's easternmost edge.  Follow the flow of the Bloodpetal seeds, and I'll wager you'll find him nearby.\n\nMy studies are limited only to seeds and other reagents, but he pursues more advanced matters.  If you are curious to learn more about Un'Goro's flora, you should speak with him now.", sourceObjective = "Report to Ithis Moonwarden in the Roiling Gardens.", completion = "Ahh... did Garl send you?  How are his studies coming?  I find that he can be a bit slow at times, but he's truly a force to be reckoned with when he takes the form of the bear.\n\nNow, we have more pressing matters to attend to.", sourceObjectiveStatus = "unverified-source-field" }
quests[24690] = { id = 24690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blazerunner", description = "I'm still a bit concerned about these fire elementals, {name}.  One last request: head to the top of Fire Plume Ridge, and kill the one they call Blazerunner.  He's the biggest and strongest of all the fire elementals in the crater.  With him gone, I'll be able to sleep much better.", sourceObjective = "Kill Blazerunner.", completion = "At last, Blazerunner is dispatched.  Thanks, {name}... he was driving me batty.", sourceObjectiveStatus = "unverified-source-field" }
quests[24691] = { id = 24691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Peculiar Delicacies", description = "Hey <bub/sweetie>, interested in making an extra dime?\n\nI've got it on good authority that some interested parties are paying BIG money for silithid legs.  Yes, you heard me right, silithid legs!  Apparently these things are delicious if you cook them right.  They're like underground lobsters, and they live just south of here.\n\nThing is, I'll need a good amount of them to pay for my overhead.  Think you could get me 8 dozen or so?", sourceObjective = "Obtain 96 Silithid Legs.", progress = "I need a lot of them because I've got to pay for shipping, handling, marketing... oh, and I've got to pay you as well.", completion = "Brilliant!  We're on the cusp of something big here, {name}.  Here's your share of the inevitably huge profits.\n\nNow, on to other matters...", sourceObjectiveStatus = "unverified-source-field" }
quests[24692] = { id = 24692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fledgling Colossus", description = "If you're here to help, then maybe you can help us with a lurking threat.\n\nTo the south lies the Slithering Scar, a quivering silithid outpost in the middle of the jungle.  You can't miss it.\n\nOne of my scouts reports that the silithid are harboring a young colossus in their large central underground chamber, and once it is fully grown, they plan to unleash it upon Un'Goro!\n\nThis must not be allowed to pass, {name}.  Find the colossus and kill it.", sourceObjective = "Kill the Gorishi Fledgling Colossus.", completion = "You've completed a remarkable task, {name}.  You are truly worthy of commendation.  Thank you, and congratulations!", sourceObjectiveStatus = "unverified-source-field" }
quests[24693] = { id = 24693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mossy Pile", description = "Here in Marshal's Stand, I can't really do too much profiteering without arousing suspicion from the scientists.  There is, however, another place where I might have use of you.\n\nMy business associate, Gremix, has a camp northwest of here, on the opposite side of the volcano.  He's a savvy business mind, and has a better eye for profit than even I do.  I'm sure he could put you to work, if you'd like to make some more coin.", sourceObjective = "Report to Gremix at Mossy Pile.", completion = "Very well, if Quixxil recommended you, then I suppose you're alright.  In all our years working together, Quixxil's never steered me wrong.", sourceObjectiveStatus = "unverified-source-field" }
quests[24694] = { id = 24694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shaper's Terrace", description = "<As you look into the orb in front of you, you hear a voice.>\n\nThe crystal pylons have been activated.  A sufficient number of crystals have been gathered.  The prerequisites have been met.  We are prepared for teleport to The Shaper's Terrace.\n\nSpeak to me when you are ready, {race}.  We will consult with The Watcher.", sourceObjective = "Speak with the Un'Goro Examinant to teleport to The Shaper's Terrace, then speak with Nablya.", completion = "I have been watching you, {name}.  Your arrival was not unforeseen.\n\nIn fact, your arrival here has been predetermined for some time now.", sourceObjectiveStatus = "unverified-source-field" }
quests[24695] = { id = 24695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ever Watching From Above", description = "When my master Khaz'Goroth shaped the world you call Azeroth, he designed Un'Goro Crater to be an area for experimentation.  You might call it the Titans' petri dish.\n\nIf you seek further knowledge about the methods in which we observe the world, pull the four levers behind me and complete my tests.", sourceObjective = "Pull the levers behind Nablya and complete her tests.", progress = "You have not yet completed my gauntlet, {name}.", completion = "You have proven to be both wise and agile, young {name}.  You have my blessing to take your newfound knowledge and spread it as you continue on your journey.", sourceObjectiveStatus = "unverified-source-field" }
quests[24697] = { id = 24697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How to Make Meat Fresh Again", description = "I don't believe we've met... I'm Nolen Tacker, Marshal Expeditions' new chief of the guards.  I'm also their chef.  There's actually more overlap than you'd think.\n\nI've got a fun little task for you.  Have you seen the spike pits around the perimeter of the camp?  See if you can convince some of the nearby dinosaurs to walk into them.  If you throw this rotten meat at them when they're not looking, it'll either make them hungry or angry.  Either way is fine, as long as they follow you into the pit!", sourceObjective = "Use the Scraps of Rotting Meat on nearby dinosaurs to lure them into the pits around Marshal's Stand.", progress = "Throw the meat, then let the dinosaurs chase you into the pit.  Easy as that!", completion = "Excellent work, {name}.  Now we're a bit safer from dinosaur attacks... plus I've got all this fresh meat to serve to my men.", sourceObjectiveStatus = "unverified-source-field" }
quests[24698] = { id = 24698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventures in Archaeology", description = "Hey, you want to try my new diemetradon dogs?  No?  Raptor risotto?  Pterrordax ptacos?\n\nFine.  Oh, I just remembered!  I have a friend nearby that might be able to use your assistance.  His name is Spark Nilminer, and he's Marshal Expeditions' chief archaeology officer.\n\nHe's been sent out to Golakka Hot Springs, to the west.  You'll likely find him on the springs' western shore.", sourceObjective = "Report to Spark Nilminer at Golakka Hot Springs.", completion = "Good ol' Nolen.  How is he doing?  Hopefully better than I am...", sourceObjectiveStatus = "unverified-source-field" }
quests[24699] = { id = 24699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gormashh the Glutinous", description = "Hey, I know!  We've been looking at the wrong tar creatures.\n\nGremix once told me about a larger-than-normal tar creature that he ran into.  It lurks around the tar pit far to the east of here, south of Fungal Rock.  I'll bet that the bigger these creatures get, the stickier they get!  We'll make some money yet, {name}!\n\nDon't forget the scraper!", sourceObjective = "Kill Gormashh and obtain the Unbelievably Sticky Tar.", progress = "I'm counting on you, {name}.  I'm invested pretty heavily into this \"tar as glue\" scheme, and it'd be a shame if you came back empty-handed.", completion = "Yes, this tar is just the stuff...\n\nHey, wait a minute, my hands... I can't seem to get them apart...\n\nMaybe this wasn't such a good idea. Oh, but wait! Super sticky tar remover! That's where the real money is!", sourceObjectiveStatus = "unverified-source-field" }
quests[24700] = { id = 24700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hard to Harvest", description = "The Lakkari Tar Pits, just north of here, conceal a hidden treasure: rare flowers that grow at the bottom of the pits.  These tarblossoms, as they're called, are valued for their beauty and their durability.  It's been a while since I last harvested tarblossoms, so there should be some new plants growing at the bottom of the pits.  Grab some for me?\n\nBy the way, good luck swimming in tar.  It's nothing like swimming in water.", sourceObjective = "Obtain 4 Tarblossom Blossoms.", progress = "Have you obtained the tarblossoms yet?  I don't see them...", completion = "Oh, there they are.  Great work, handsome!  Here's some gold.  You've earned it.", sourceObjectiveStatus = "unverified-source-field" }
quests[24701] = { id = 24701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marshal's Refuse", description = "A big part of making money is shamelessness.  You have to be willing to profit off of the misfortune of others.  It all ends up boiling down to one question: How much do you love money?\n\nWhen Marshal and his crew abandoned their refuge up to the north, they left behind lots of supplies.  This stuff isn't rare, or even particularly valuable, but it's there if you're willing to take it.  His camp is up in the cliffs, to the north.\n\nOh, and be on the lookout for whatever it was that made them leave...", sourceObjective = "Obtain 10 Discarded Supplies.", progress = "Did you find anything good?", completion = "It's a bunch of junk, but it's a bunch of FREE junk, and that's all that matters to me.\n\nWell, mostly free.  Here's your share.  Thanks!", sourceObjectiveStatus = "unverified-source-field" }
quests[24702] = { id = 24702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Here Lies Dadanga", sourceObjective = "Obtain 10 Bloodpetal Sprouts.", progress = "Sturdy mount and trusted friend.\n\nDied shortly after the Cataclysm.  He always hated loud noises.\n\nIn lieu of flowers, please drop off a few Bloodpetal sprouts.  In life, he loved nothing more.", completion = "<You almost sense an air of gratitude as you place the Bloodpetal sprouts on the grave.>", sourceObjectiveStatus = "unverified-source-field" }
quests[24703] = { id = 24703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Important Lesson", description = "What ho, traveler!  You must know that you set foot upon the camp of Maximillian of Northshire!  Mayhap you have heard tales sung of my many exploits?  I can see from the look in your eye that you have.  That glint of recognition plays upon your visage like the White Lady's reflection o'er Stonecairne Lake.\n\nIt is clear to me that you seek adventure.  As you seem able enough, and thoroughly well-intentioned, I would offer to make you my squire.", sourceObjective = "Speak to Maximillian of Northshire to learn more about becoming a squire.", progress = "Your first quest is a simple one, yet it somehow remains unfinished.  Endure my words and become my squire.", completion = "You please me, {name}.  From this day forward, you are no longer a simple beggar, but a squire loyal to Maximillian of Northshire.  Prepare yourself for our first sally, good squire, for together we shall plunge our fists elbow-deep into what they call adventure!", sourceObjectiveStatus = "unverified-source-field" }
quests[24704] = { id = 24704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Evil Dragons of Un'Goro Crater", description = "This crater is filled with a malignant breed of dragon.  Have you seen them?  They wander all about, parading their spiky backs and lizardy faces all around the Crater.\n\nDon't let them fool you, squire, for these dragons are no minions of graceful Alexstrasza.  They are clearly vicious, and direly in need of a hero's blade.\n\nI have decided that I will slay no less than 15 of them.  As my squire, you must come along.  Should we become separated, you may meet me back here at the Hot Springs.", sourceObjective = "Help Maximillian of Northshire slay 15 \"Dragons\".", completion = "...and that makes 15 of them.\n\nJustice had a name today... and that name was Maximillian of Northshire.  For Doloria!", sourceObjectiveStatus = "unverified-source-field" }
quests[24705] = { id = 24705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Town Dwellers Were Made to be Saved", description = "I've a feeling that we may find more than dragons here in this crater.  My paladin's instinct tells me that there are townsfolk nearby that require our aid. Those in distress cannot be ignored.\n\nLet us sally forth, Squire {name}!  The people of Un'Goro require our aid!", sourceObjective = "Rescue the Dweller by the Shore, the Dweller in the Cliffs, and the Dweller of the North.", completion = "Our duty is fulfilled.  Even so, it troubles me that the people of today are less than gracious...   Perhaps tomorrow we shall experience proper thankfulness.\n\nNow we must ride.  More adventures await!", sourceObjectiveStatus = "unverified-source-field" }
quests[24706] = { id = 24706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spirits of Golakka Hot Springs", description = "A moment of seriousness now, {name}.  We have an important quest ahead of us.  The treacherous dragons that plague this valley will not cease their mischief until we destroy their repugnant brood mother.  Before we even attempt to complete such a task, we must ask the Light for aid.\n\nI have seen the Light manifest itself nearby, in the form of Spirits floating by the shores of Golakka Hot Springs.  Come, I must speak with them, and ask them for aid.", sourceObjective = "Stand by as Maximillian of Northshire speaks to 2 Steam Furies.", progress = "We have not completed our prayers.  Shall I join you?", completion = "Might I ask you a question?  What act have you committed to make the spirits so angry at you?  I'm impressed that you had the patience to sit so still while they pummeled you so violently.\n\nNow we may proceed.  The teeth and scales of Un'Goro's greatest dragon await us.", sourceObjectiveStatus = "unverified-source-field" }
quests[24707] = { id = 24707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ballad of Maximillian", description = "The time we have waited for is upon us, Squire {name}.  Un'Goro's brood mother will perish at my hands.  The gravity of our task weighs heavily on me, but with the power of the Light behind us, we are guaranteed to succeed.\n\nAre you ready to depart?", sourceObjective = "Help Maximillian of Northshire kill the Devilsaur Queen. If you become separated from Maximillian, meet him at Golakka Hot Springs in Un'Goro Crater.", progress = "We should attempt the slaying one more time, I think.", completion = "The day is saved!  Huzzah!  Today we learned that while armor can be replaced, valor has no price.\n\nBecause of your key involvement in this task, I hereby graduate you from squire to fledgling knight.  No longer do the chains of servitude bind you to me; you are free to serve other masters.\n\nGo with honor, young hero!  For chivalry, the Light, and the beauty of Doloria!", sourceObjectiveStatus = "unverified-source-field" }
quests[24708] = { id = 24708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fossil-Finder 3000", description = "One of the things I hate the most about digging is the fact that half the time, all you find is dirt.  That's why I've been spending most of my time out here tinkering instead of digging.\n\nLet me show you what I've invented: the Fossil-Finder 3000.  I just put the finishing touches on it.  If it works properly, it should find the largest fossils in the area.  I know, sweet, huh?\n\nTest it out and see if you can find some ridiculously big dinosaur bones.", sourceObjective = "Obtain an Enormous Dinosaur Talon.", progress = "Have you found anything?  Did it work?", completion = "What an interesting femur you've brought here, but why's it all sharp and curvy?\n\n...\n\nWait a minute, that thing's a TALON?  A dinosaur with a talon that size would've been... well, really big, that's for sure.  Is this the only fossil that you found there?", sourceObjectiveStatus = "unverified-source-field" }
quests[24709] = { id = 24709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tale of Two Shovels", description = "Hey wait a minute, this bone has pickax marks on it.  These aren't yours, are they?  No, I recognize this mark... this must be that blasted dwarf!  Gah!\n\nLet me step back for a minute and explain.  There's another archaeologist south of here named Durrin Direshovel.  He practices a reckless, devil-may-care brand of archaeology that offends even me.\n\nA priceless fossil, ruined by sloppy pick-work.  This is the last straw, Durrin!\n\n{name}, go put an end to Direshovel and his negligent excavation.", sourceObjective = "Kill Durrin Direshovel and obtain Durrin's Archaeological Findings.", progress = "Is the deed done?  Did you manage to salvage his notes?", completion = "I knew it!  Durrin HAS been digging around here.  And he's been excavating what could be the archaeological find of the century!  Now I just have to find out where he's stashing the bones...\n\nThanks {name}.  You've been a great help.", sourceObjectiveStatus = "unverified-source-field" }
quests[24710] = { id = 24710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deliverance from the Pit", description = "We need to make our way up the main path and through the cave to Tyrannus' rise.\n\nHe will be forced to confront us there lest we make our way into the citadel proper.\n\nGo now, {class}. My men and I will be there to stand by you when the confrontation with Tyrannus comes.", sourceObjective = "Kill Scourgelord Tyrannus.", completion = "Such a senseless waste! Arthas goes too far! I can only hope what we find in the Halls of Reflection makes this somehow worth it.\n\nIf what that vile gnome said is to be trusted, Frostmourne should be there, and with it, answers to confronting Arthas.", sourceObjectiveStatus = "unverified-source-field" }
quests[24711] = { id = 24711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostmourne", description = "We must press on, hero. We've come so far... we're so close to our goal.\n\nI must delay a moment to send Elandra back to the airship. I'm uncertain how we're going to escape with so many men lost and so few to keep our path in secure.\n\nContinue on. I will meet you in the Halls of Reflection.", sourceObjective = "Meet Lady Jaina Proudmoore at the entrance to the Halls of Reflection.", completion = "The Halls of Reflection. Finally.\n\nLet me know when you are ready. Arthas may not be here, but it would be naive to think that he would leave Frostmourne unguarded entirely.", sourceObjectiveStatus = "unverified-source-field" }
quests[24712] = { id = 24712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deliverance from the Pit", description = "We need to make our way up the main path and through the cave to Tyrannus' rise.\n\nThere, he will be forced to confront us there lest we make our way into the citadel proper.\n\nGo now, {class}. My men and I will be there to stand by you when the confrontation with Tyrannus comes.", sourceObjective = "Kill Scourgelord Tyrannus.", completion = "The Halls of Reflection lie ahead. If what that vile gnome said is to be trusted, Frostmourne should be there, and with it, answers to confronting Arthas.", sourceObjectiveStatus = "unverified-source-field" }
quests[24713] = { id = 24713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostmourne", description = "Keep moving, the sword is close.\n\nI need a moment to send one of my dark rangers back to the airship. With all of our fodder gone, I will not be caught unprepared - we will need any help they can send.\n\nGo. I will meet you in the Halls of Reflection.", sourceObjective = "Meet Lady Sylvanas Windrunner inside the entrance to the Halls of Reflection.", completion = "The Halls of Reflection. Finally.\n\nLet me know when you are ready, {class}. I will not be so naive as to think that Arthas left his precious sword entirely unguarded.", sourceObjectiveStatus = "unverified-source-field" }
quests[24714] = { id = 24714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chasing A-Me 01", description = "Unfortunately, something's happened to one of my greatest inventions.  You've seen mechanical squirrels, yes?  Well, to get closer to the apes of Un'Goro Crater, I created a mechanical ape to blend in with their kind--I call her A-Me 01.\n\nShe has been studying the local wildlife at Fungal Rock for several months, but she should have returned by now.  I fear the worst for her.\n\nCan you help me find her?", sourceObjective = "Find A-Me 01 at Fungal Rock.", completion = "A-Me lies motionless before you.  No power seems to be running through her components.", sourceObjectiveStatus = "unverified-source-field" }
quests[24715] = { id = 24715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repairing A-Me 01", description = "<Suddenly, the robotic gorilla's eyes light up, and it begins to speak.>\n\n\"...operational capacity... less than 5%... accidentally... punctured oil reservoir...\"\n\n\"...use coconut milk... rock... save A-Me 01...\"\n\n<A-Me closes her eyes.>", sourceObjective = "You're pretty sure that A-Me 01 has asked you to obtain an Un'Goro Coconut, crack it on the rock nearby, and give her the High Viscosity Coconut Milk.", progress = "<A-Me 01 has gone into power save mode.>", completion = "You pour the coconut milk into what appears to be A-Me 01's oil reservoir.  You hear the sound of gears whirring and actuators firing.", sourceObjectiveStatus = "unverified-source-field" }
quests[24717] = { id = 24717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Apes of Un'Goro", description = "There's plenty of money to be had here in Un'Goro, you just need to know where to look!\n\nApes may be common here in Un'Goro, but they're much rarer up north.  In Everlook, a gorilla hide fetches ten times what you'll get for it down here!\n\nI'm not going to send you all the way up to Winterspring - that'd be irresponsible - but I could use your help actually obtaining some hides.\n\nYou'll find gorillas at Fungal Rock, to the northeast, near a waterfall.  Don't forget to check inside the cave!", sourceObjective = "Bring 2 Un'Goro Gorilla Pelts, 2 Un'Goro Stomper Pelts, and 2 Un'Goro Thunderer Pelts to Gremix at Mossy Pile.", progress = "I never know what style is in vogue, so I'll want a few different colors.  Try to get hides from each different type of gorilla there.", completion = "Wow, 2 of each color!  You're certainly an overachiever, {name}.  My companions and I could use a {race} like you around here.  Ever consider a career in profiteering?", sourceObjectiveStatus = "unverified-source-field" }
quests[24718] = { id = 24718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mighty U'cha", description = "Looking around, you see bits of red fur laying around this part of the cave.  It appears to match the consistency of gorilla fur.\n\nBased on your conversations with Gremix, you know that he would almost certainly be interested in a red gorilla hide, if you were to obtain one.", sourceObjective = "Bring U'cha's Pelt to Gremix at Mossy Pile.", progress = "Red fur?  What're you waiting for!  Go back and get that red gorilla!  I'll pay you double!", completion = "Wow, look at this one!  Not just the color, but the size of it... you could cover a tauren with this.\n\nHere you go, {name}.  You've earned this.  Stick around, I'm sure we can find something else for you to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[24719] = { id = 24719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Claws of White", description = "Stop, {race}.  I could use the help of a {class} like you.\n\nRight outside this camp, there are raptors with deadly claws.  I've been using the claws for druid rituals, but it doesn't seem to be working.  However, I did notice that some of those raptors sometimes have white claws, when most have deathly black ones.\n\nThe earth works in strange ways.  Maybe you could fetch me some of the white claws, and I'll try one last time?", sourceObjective = "Obtain 5 White Ravasaur Claws.", progress = "Have you gotten any of the claws yet?", completion = "My mentor says that sometimes you have to take away from nature before you can give back.  These raptors... I feel that they died for good cause.\n\nThank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24720] = { id = 24720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystals of Power", description = "I'm sure you've noticed 'em, {name}. They're everywhere!\n\nWhat am I talking about? Why, the crystals, of course!\n\nThe crystals... They're all over the crater. Most people ignore them, but I have a strange feeling that they hold power within them.\n\nSay, I'm running a little low on the crystals I have here -- think you might be able to collect some more for me?  \n\nYou'll find yellow crystals to the northwest, red crystals to the... oh, I'm sure you'll figure it out.", sourceObjective = "Collect 7 Power Crystals of each color: red, blue, yellow, and green.", progress = "I just know I'm onto something here, {name}!", completion = "Now I will continue my experiments! Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24721] = { id = 24721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eastern Pylon", description = "High up in the cliffs above me there is a large crystal pylon.  Who placed it there, I cannot say, nor can I determine any reason that it would be built in such a strange place.\n\nMaybe you can make more of it than I can.  I personally don't care what it does, so you needn't report back to me, but perhaps one of the scholars in Marshal's Stand might be interested in what you discover.", sourceObjective = "Touch the Eastern Crystal Pylon in Un'Goro Crater.", completion = "You were right to bring this pylon to my attention, {name}.  This is just the sort of thing I've been studying.", sourceObjectiveStatus = "unverified-source-field" }
quests[24722] = { id = 24722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Northern Pylon", description = "You've done us a number of favors, {name}... now let Gremix do one for you.  The attacks on Marshal's Refuge were terrible, undoubtedly.  They came without warning, and took no prisoners.  They were lucky that so many of them survived.\n\nA few weeks ago, I came across a crystal pylon in the cliffs to the northeast of here, east of Marshal's Refuge.  I think the pylon and the attacks may be related somehow.  Maybe you can investigate?  I'm sure someone in Marshal's Stand will thank you.", sourceObjective = "Discover the location of the Northern Crystal Pylon in Un'Goro Crater.", progress = "Yes, {name}?", completion = "You think this may be related to the attacks on Marshal's Refuge, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[24723] = { id = 24723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Western Pylon", description = "Durrin's research touched on one area that intrigues me: a potential link between the titans and the dinosaurs.  J.D. Collie back at camp is always talking about titan this and crystal that... maybe she'd be interested.\n\nBefore you report to her, you might want to check out the crystal pylon not far from here.  It's just up in the cliffs, to the west of here.  It's got crystals on it, and it always seemed to me like it might have something to do with the titans.", sourceObjective = "Discover the location of the Western Crystal Pylon.", completion = "A pylon in the west?  And a relationship between titans and dinosaurs?  This is a lot to take in, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24724] = { id = 24724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Restore", progress = "The Pylon table allows you to combine green power crystals with yellow power crystals.\n\nAccording to J.D.'s manual, this combination can be used to heal yourself or your allies.", completion = "Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.\n\nThe resulting combination is now yours." }
quests[24725] = { id = 24725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Charge", progress = "The Pylon table allows you to combine red power crystals with yellow power crystals.\n\nAccording to J.D.'s manual, this combination can be used to create a large explosion that can inflict damage on your enemies.", completion = "Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.\n\nThe resulting combination is now yours." }
quests[24726] = { id = 24726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Force" }
quests[24727] = { id = 24727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Spire", progress = "The Pylon table allows you to combine blue power crystals with yellow power crystals.\n\nAccording to J.D.'s manual, this combination can be used to create a shield that does damage to enemies.", completion = "Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.\n\nThe resulting combination is now yours." }
quests[24728] = { id = 24728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Ward", progress = "The Pylon table allows you to combine green power crystals with red power crystals.\n\nAccording to J.D.'s manual, this combination can be used to strengthen the protection you have against physical damage.", completion = "Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.\n\nThe resulting combination is now yours." }
quests[24729] = { id = 24729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Yield" }
quests[24730] = { id = 24730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Roll the Bones", description = "You'd think that being chief digger for Marshal Expeditions means I like digging.  There might be worse things to do in this world... but none really leap to mind.\n\nWe were supposed to be digging in Terror Run - FANTASTIC name by the way - for dead stegodons and diemetradons.  Well, there are plenty of live ones there too!  Wil and Hol are still all about studying this death trap, so we need those dinosaur bones.  Between you and me though, bringing some from live ones will work out just as well.", sourceObjective = "Obtain 8 Dinosaur Bones.", progress = "Think whatever you want of me, but they're not going to care if the bones they get to research are from ancient stegodons and diemetradons or the ones that almost devoured us wholesale when we were trying to set up our camps.  I'll just be happy if we get out of here alive...", completion = "Excellent, these should do the trick.  And now, if you'll permit me, in case anyone's listening...\n\nTHANKS FOR DIGGING ALL OF THESE BONES OUT OF THE GROUND FOR US AND NOT HURTING THE NATIVE BEASTS IN ANY WAY.\n\nWhether you really did or didn't, I don't want to know.  Let's keep it that way, shall we?  Here - maybe this will keep your lips shut on the whole thing.  Anything to get out of here alive, I say!", sourceObjectiveStatus = "unverified-source-field" }
quests[24731] = { id = 24731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fare of Lar'korwi", description = "Once, a long time ago, a brother of mine took some meat from one of Lar'korwi's kills. He didn't know it at the time, but Lar'korwi saw him from the forest. Lar'korwi followed my brother for days, destroying everything he touched. My brother, scared, finally decided to run from the Crater and leave Lar'korwi behind.\n\nLar'korwi killed him not far from this spot.\n\nIf you want to provoke Lar'korwi, find a fresh kill of his and take some of the meat from it.\n\nStart your search to the west.", sourceObjective = "Find the carcass of Lar'korwi's freshest kill and steal a Piece of Threshadon Carcass.", progress = "Do not take my words lightly, {name}. If you truly wish to face this creature, then you must be careful... and smart. It will take a great deal of strength and insight to draw out Lar'korwi and defeat him.", completion = "This will do nicely, {name}. It seems Lar'korwi eats well these days. Although, I wonder where he found a threshadon in this area. Odd.\n\nRegardless, I will hold onto this until you are ready for your confrontation with the beast. Do not worry for my safety--I am sure you've angered Lar'korwi enough that he will not kill me until after he's tasted your flesh.", sourceObjectiveStatus = "unverified-source-field" }
quests[24732] = { id = 24732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scent of Lar'korwi", description = "I'm actually surprised he has not come for you yet, {name}. But all is well, for I have a final plan that will bring the monster to us.\n\nBeing the dominant male gives Lar'korwi rights to breed with any female he chooses--and he chooses many of them. You'll find many ravasaur eggs to the west of here. Get close to them and you should provoke an attack by his mates. The females produce an awful smell from a gland in their heads that allow males to know they are ready to breed. Bring me two of those glands.", sourceObjective = "Obtain 2 Ravasaur Pheromone Glands.", progress = "Be careful, {name}. Getting close to any nest of eggs surely will provoke the mothers... even if you've already secured a gland from one. The mothers can be just as deadly as Lar'korwi himself when they fight to protect their young. But, if you are successful, then we shall have a definitive way of bringing Lar'korwi out from hiding.", completion = "Ah, fine specimens, {name}. The two pieces you've found should be perfect for baiting Lar'korwi into the open. I cannot wait to see the outcome of your fight with the monster. He is a massive thing with claws as sharp as the finest blades. You will look into his eyes and you will know death.", sourceObjectiveStatus = "unverified-source-field" }
quests[24733] = { id = 24733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bait for Lar'korwi", description = "This will be the most difficult part because there is some complexity to the plan.  Continue following the river to the north, and look for a bend in the river.  It was here I saw Lar'korwi last.  You will know you are in the right area because of all the bones from massive creatures that once wandered nearby.\n\nTake the meat you recovered and place it there.  Then, rub this mixture I created on the meat.\n\nIf both lures mingled together do not bring Lar'korwi to you, then I know nothing else that will.", sourceObjective = "Using the contents of Torwa's Pouch, summon Lar'korwi and defeat him. Then bring Lar'korwi's Head to Torwa Pathfinder near the entrance to Un'Goro Crater.", progress = "Do not let fear overpower you, {name}. Fear is the great betrayer... you must remain strong!", completion = "The Earth Mother be praised! You've done it! Fair play to you, {name}. You have proven to be a great hunter in your own right. Your spirit is strong. Your bravery unmatched. And your strength has been fortified. I bow down to your skills.\n\nOnly the greatest of my ancestors could have accomplished something so incredible. Congratulations.", sourceObjectiveStatus = "unverified-source-field" }
quests[24734] = { id = 24734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost!", description = "You've got to help me, {name}! My friend, Ringo left earlier to explore the volcano to the north of here, and he has been gone way too long. I am really worried about him.\n\nDo you think you could find him? Why don't you take my canteen with you -- if you do find Ringo, I'm sure he'll need it!", sourceObjective = "Find signs of Ringo at Fire Plume Ridge.", progress = "Ringo's sack rests on the rock in front of you.", completion = "You find what appears to be Ringo's belongings.  If he left these here, he can't have gone far away.  Maybe you should look for him.", sourceObjectiveStatus = "unverified-source-field" }
quests[24735] = { id = 24735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Help From My Friends", description = "Ugh... It's so hot...\n\nI was exploring this area, when all of a sudden, the heat just became unbearable. I must be suffering from heat exhaustion.\n\nPlease, help me get back to my friend Spraggle at Marshal's Stand. I think I'm well enough to follow you there.\n\nI am feeling a little out of it, so you can slap me if I'm feeling woozy.  If I do happen to faint again, just splash some water on me from Spraggle's canteen. That should work, I hope...", sourceObjective = "Lead Ringo to Spraggle Frock at Marshal's Stand.\n\nIf Ringo feels weak, slap him. If he faints, use Spraggle's Canteen to revive him.", progress = "I've been so worried about Ringo...", completion = "Ringo's not in the best shape, {name}, but I am glad to have him back in one piece!\n\nThank you for finding him.", sourceObjectiveStatus = "unverified-source-field" }
quests[24736] = { id = 24736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shizzle's Flyer", description = "I'm making a flying machine!\n\nI got stranded here, and I'm absolutely horrible at finding my way around. I'd take a gryphon or wind rider back to Gadgetzan, but those beasts just scare me to death.\n\nSo, will you help me? All I have left to build is the wings, and I was thinking that the webby scales from the pterrordax in the Screaming Reaches to the west would be perfect. There's no way I'm going to go up against one of those, but you look pretty tough. Why don't you give it a try?", sourceObjective = "Collect 35 Webbed Pterrordax Scales.", progress = "Every great vehicle needs a name... I was thinking I'd call it... Pwned!", completion = "Yes, these scales are perfect. I should be able to get this flyer off the ground with these scales for sure!\n\nThanks!", sourceObjectiveStatus = "unverified-source-field" }
quests[24737] = { id = 24737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Super Sticky", description = "I'm always looking for a quick way to earn a gold, {name}. If you help me with my newest idea, I'll let you in on a little of the profit. How does that sound to you?\n\nI thought so!\n\nWe're going to be making some glue. Head to the tar pits just north of here, and collect me some tar. Not just any tar, now, you'll need to get it from the beasts that live around the tar pits. As a bonus, if you use my tar scraper on their corpses, you'll keep your hands nice and clean.", sourceObjective = "Collect 8 samples of Super Sticky Tar.", progress = "Tara's done it again -- this super sticky glue will be all the rage!", completion = "Yeah, this tar is pretty sticky, I guess.  I mean, it's sticky, but it's not \"make fistfuls of money\" sticky.  I guess I'll have to keep thinking.", sourceObjectiveStatus = "unverified-source-field" }
quests[24740] = { id = 24740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Volcanic Activity", description = "Welcome.  I'm Williden Marshal, and my sister and I run this expedition of explorers and scientists.  You have a moment?\n\nI don't like the look of those elementals on that volcano, {class}.  We have too much equipment, too many notes... one crazed elemental could streak its way through our camp and do terrible, terrible damage.\n\nShow them that their new neighbors aren't to be trifled with.  And bring back the ash that they leave behind... we might as well do a little science while we're at it.", sourceObjective = "Collect 9 samples of Un'Goro Ash from the fire elementals around the volcano in Un'Goro Crater.", progress = "Do you think the volcano is active?  I wonder why it didn't explode when the cataclysm hit.", completion = "I hope that did the trick.  I'll take the ash... this may come in handy sometime down the line.", sourceObjectiveStatus = "unverified-source-field" }
quests[24741] = { id = 24741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trading Up", description = "Hobart thinks he's going to feed us on those tiny clucker eggs? Bah! We're going to get some real eggs!\n\nI've already set up some traps on the Raptor Rise up the path to the east. Take this bunch of wild clucker eggs and lay them in the traps. The spiny raptors will go right after the clucker eggs, and then you'll get to trade up to their larger eggs.\n\nGenius!", sourceObjective = "Gather 5 Spiny Raptor Eggs.", progress = "How many did you get? I can just taste the massive omelet we're going to cook up now!", completion = "Nice! Look at the size of those things!\n\nThere's no way that Grapplehammer's going to be able to top those!", sourceObjectiveStatus = "unverified-source-field" }
quests[24742] = { id = 24742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding the Source", description = "I created a thermometer to take readings of the temperatures at the volcano, and I'd like to find the hottest lava flows.  It gives the measurements in degrees Kraklenheit!\n\nHere, take it, and take readings of the temperatures at the ridge whenever you see a hot spot!\n\nHot spots usually take the form of a glowing, rocky pillar jutting out of the ground.  You'll find them around the base of Fire Plume Ridge... one trip around the perimeter will likely suffice.", sourceObjective = "Krakle in Un'Goro Crater wants you to find the hottest area of Fire Plume Ridge.\n\nWhenever you find a hot spot, use the thermometer to check the temperature. Keep looking until you find the hottest one.", progress = "I'd go there myself, but... I'm a little scared of the fire elementals there!", completion = "These results are astounding!  My boss will be pleased.  Thank you, kind {race}!", sourceObjectiveStatus = "unverified-source-field" }
quests[24743] = { id = 24743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow's Edge", sourceObjective = "Listen well, {class}. In accepting this weapon your fate is sealed.\n\nOvercome or succumb.\n\nI have placed your feet upon this path. You are therefore my personal responsibility. Should you falter, I am duty-bound to deliver you from this life.\n\nRemember my words, {race}, and do not fail.", sourceObjectiveStatus = "unverified-source-field" }
quests[24744] = { id = 24744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Biggest Egg Ever", description = "Bamm Megabomb? Who does he think he is? His spiny raptor eggs are no match for what we are about to recover!\n\nAs you well know, each Town-In-A-Box is equipped with a micro mechachicken for just such a dietary emergency. Luckily for us, my keen intellect was able to deduce the location that our prodigious, pre-programmed poultry ran off to.\n\nHead north to the Scorched Gully. But beware, its circuit boards are fried and I imagine it's not so micro any longer!", sourceObjective = "Recover the Biggest Egg Ever.", progress = "Just think about the accolades that will rain down upon me... us, when the Biggest Egg Ever is returned!", completion = "Eureka! My genius saves the day yet again! Take that Bamm Megabomb!\n\nAnd now, to reap the benefits!", sourceObjectiveStatus = "unverified-source-field" }
quests[24745] = { id = 24745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something is in the Air (and it Ain't Love)", description = "The inside of the card is scribbled with mad, detailed plans to infect most of Azeroth.  You should show this to one of Steamwheedle's investigators immediately!", sourceObjective = "Bring the Faded Lovely Greeting Card to Inspector Snip Snagglebolt in Stormwind.", progress = "Did you take care of those no-good scheming villains?", completion = "What've you got there?\n\nOh hey, this is big. Real big. Most of the crazy details in one little package. Thanks - you really helped us reel this all in. Good working with ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24746] = { id = 24746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[24747] = { id = 24747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sabotage!", description = "These dwarven artillery shells have a built-in airburst timer. This is easy! Just sabotage one of the artillery shells in the loading bay and then hoist it up into the magazine. Boom, baby. BOOM!\n\nYou'll find the shells in one of two loading bays behind the main garage on this level. It's right around the corner.\n\nOnce you've rigged the artillery shell... Run! Run like the wind, {name}! Then report to Gann back at camp. I'll be right behind you.", sourceObjective = "Sabotage a Dwarven Artillery Shell and then flee from Bael'Dun before it explodes.", completion = "Bael'dun? Destroyed?\n\n<Wincing in pain, Gann twists his head to peer behind him, where plumes of smoke darken the skyline.>\n\n{name}, my friend. You have avenged Taurajo and avenged the Tauren people. The invaders will not soon recover from that blow. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[24748] = { id = 24748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lich King's Last Stand", description = "Shadowmourne; a newly forged weapon already steeped in this world's history, reborn into an unrivaled destiny.\n\nWith this weapon you bear a solemn responsibility, and the time to carry out that charge is at hand.\n\nTake this weapon of myth and legend and march on the enemy. Avenge the countless heroes lost in his merciless campaign. Bring rest to their tortured souls.\n\nSteel yourself, {class}, and guide Shadowmourne to fulfill the purpose of its creation.", sourceObjective = "Highlord Darion Mograine in Icecrown Citadel wants you to kill the Lich King.", completion = "So, at last it is done.\n\nMay the people of Azeroth remember our deeds here forevermore. May the sacrifices of so many burn in their hearts eternally. May they never fail to risk mortal peril in the face of great evil.", sourceObjectiveStatus = "unverified-source-field" }
quests[24749] = { id = 24749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unholy Infusion", description = "Before your weapon can reach its full potential it must be endowed with its signature powers. First among them is unholiness.\n\nYou must seek out and defeat the one called Professor Putricide, but his death is not your only goal. You must use his resources against him.\n\nFind a way to absorb his mutated slime. Use the foul substance to infuse your weapon with the power of the unholy. Only when this has been done shall I reveal your next task.", sourceObjective = "Highlord Darion Mograine wants you to infuse Shadow's Edge with Unholy power and slay Professor Putricide.\n\nThis quest may only be completed in 25 person difficulty of Icecrown Citadel.", completion = "Well done, {class}.\n\nThe completion of our work draws near.", sourceObjectiveStatus = "unverified-source-field" }
quests[24750] = { id = 24750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rise of the Darkspear", description = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here.\n\nVol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream.\n\nNo, dis time we not fleein'. Dis time, we are fightin' for a home dat will last.\n\nIt's time to begin ya trainin', {name}. Speak with Soratha to the east.", sourceObjective = "Meet with Soratha in the Darkspear Training Grounds.", completion = "Anotha newblood, eh?\n\nYa actually have an intense look about ya though. Fiery eyes. You might have the makings of a real {class}.\n\nLets not waste anymore time 'den.", sourceObjectiveStatus = "unverified-source-field" }
quests[24751] = { id = 24751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Basics: Hitting Things", description = "Alright, mon. We start simple. I need ta know dat you know the basics of the arcane arts.\n\nGo thrash dose tiki targets. Take it slowly. Natural-like. I'll watch how you form your casts and we'll go from dere.", sourceObjective = "Destroy 6 Tiki Targets.", completion = "Not bad, mon. Ya have a natural flow to ya spells - you may have a talent for dis.\n\nSome rough edges ta be sure, but we'll get dose ironed out here and I'll teach ya a few new tings as we go.", sourceObjectiveStatus = "unverified-source-field" }
quests[24752] = { id = 24752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arts of a Mage", description = "As ya' develop ya' powah, ya' gonna start to tink of new spells, new ways to use ya' arcane talents. \n\nGo now, grow ya' skills, and 'den come back an' show me what 'cha figure out.", sourceObjective = "Reach level 3 to learn Frost Nova. Practice using it 2 times against a Tiki Target.", completion = "Good work, mon! Dis stuff come easy to ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24753] = { id = 24753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rough Start", description = "Lets put dose skills ta use. I'll start ya off easy, mon.\n\nThere be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight.\n\nDey're all over the island. Bring me some cat pelts.", sourceObjective = "Retrieve 6 Wildmane Cat Pelts.", progress = "I doubt dey too much of a challenge, mon, but they'll still claw up ya ankles if ya don't stay quick footed.", completion = "Dese are some fine pelts, boy. We could make some hefty cloaks outta dese.", sourceObjectiveStatus = "unverified-source-field" }
quests[24754] = { id = 24754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proving Pit", description = "Ya done quite well for ya'self, {class}. I'm sure I could teach ya a trick or two here and dere, but I not be wastin' ya time on tiki targets no longer.\n\nl put one last trial before ya den, mon. Head over to da provin' pit in the middle of dis area and fight a real baddy - one dat wants ta kill ya back. Just let the jailor by the pit know when ya ready.", sourceObjective = "Speak to a Darkspear Jailor, then enter the proving pit and kill a Captive Spitescale Scout.", completion = "Ya handle yerself quite well. Ya gonna be quite powerful some day.", sourceObjectiveStatus = "unverified-source-field" }
quests[24755] = { id = 24755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Than Expected", description = "Ya definitely more den expected, mon. I'm sure dere's more important stuff we can be usin' ya talents on now. Ya don't need ta hang out with da newbloods no more.\n\nHead down to da village to da southeast and make yaself known. Lend a hand here and there and I'm sure ya make yer way up to sometin' more prestigious quick enough.", sourceObjective = "Report to Vol'jin at Darkspear Hold.", completion = "Ya tha new recruit everyone's talkin' about, eh? Welcome ta tha Darkspear.", sourceObjectiveStatus = "unverified-source-field" }
quests[24756] = { id = 24756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Infusion", description = "Your weapon is ready to be endowed with the power of blood.\n\nYou must face Queen Lana'thel in battle and subject yourself to her Blood Mirror. This will cause Shadow's Edge to drink the blood of the nearest living being. That being would be you, {race}.\n\nOnce the blade has been thus awakened, allow the Queen's Frenzied Bloodthirst to take hold of you, feed the blade thrice to sate it, and then give the queen an ignominious death.\n\nMay her screams pierce the ears of the Lich King as he awaits his fate.", sourceObjective = "Highlord Darion Mograine wants you to infuse Shadow's Edge with blood and defeat Queen Lana'thel.\n\nThis quest may only be completed in 25 person difficulty of Icecrown Citadel.", completion = "Well done, {class}.\n\nShadowmourne is nearly within reach.", sourceObjectiveStatus = "unverified-source-field" }
quests[24757] = { id = 24757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frost Infusion", description = "Shadow's Edge is prepared to receive its final infusion of power.\n\nSindragosa, the enemy's own mount, must fall. But before she is brought down, you must sustain four of her frozen breath attacks without tasting death.\n\nWithout his dragon, nothing shall stand between you and the Lich King.", sourceObjective = "Highlord Darion Mograine has instructed you to slay Sindragosa after subjecting yourself to 4 of her breath attacks while wielding Shadow's Edge.\n\nThis quest may only be completed in 25 person difficulty of Icecrown Citadel.", completion = "The axe has drunk its fill, {race}, and the forge is nearly ready for the creation of Shadowmourne...", sourceObjectiveStatus = "unverified-source-field" }
quests[24758] = { id = 24758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rise of the Darkspear", description = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here.\n\nVol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream.\n\nNo, dis time we not fleein'. Dis time, we are fightin' for a home dat will last.\n\nIt's time to begin ya trainin', {name}. Speak with Nekali to the east.", sourceObjective = "Meet with Nekali in the Darkspear Training Grounds.", completion = "Anotha newblood, eh?\n\nYa actually have a weathered look about ya though. Wise eyes. You might have the makings of a real {class}.\n\nLets not waste anymore time 'den.", sourceObjectiveStatus = "unverified-source-field" }
quests[24759] = { id = 24759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Basics: Hitting Things", description = "Alright, mon. We start simple. I need ta know dat you know the basics of the natural arts.\n\nGo thrash dose tiki targets. Take it slowly. Natural-like. I'll watch how you form your casts and we'll go from dere.", sourceObjective = "Destroy 6 Tiki Targets.", progress = "Power isn't da end all of defeating ya enemy, and it most certainly isn't tha end all of stayin' alive. Fightin' is about balance. Everytin has its time and place.", completion = "Not bad, mon. Ya have a natural flow to ya spells - you may have a talent for dis.\n\nSome rough edges ta be sure, but we'll get dose ironed out here and I'll teach ya a few new tings as we go.", sourceObjectiveStatus = "unverified-source-field" }
quests[24760] = { id = 24760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arts of a Shaman", description = "As ya grow in powah, you begin ta discovah the voices of da ancestahs speakin' to ya, teachin' you dere secrets.\n\nTha first of 'dese is to focus tha power of da elements into yer weapon. It allows ya to unleash a quick, vicious attack on your enemies. Dis should be easy enough for ya to make a lot of use of it.\n\nTry it out. Let me know when ya tink you have it down.", sourceObjective = "Reach Level 3 to learn Primal Strike, and then use Primal Strike 3 times against a Tiki Target.", progress = "Der are many other ways to enchant yer weapon. Ya'll learn more wit time.", completion = "Good work, mon! Dis stuff come easy to ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24761] = { id = 24761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rough Start", description = "Lets put dose skills ta use. I'll start ya off easy, mon.\n\nThere be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight.\n\nDey're all over the island. Bring me some cat pelts.", sourceObjective = "Retrieve 6 Wildmane Cat Pelts.", progress = "I doubt dey too much of a challenge, mon, but they'll still claw up ya ankles if ya don't stay quick footed.", completion = "Dese are some fine pelts, boy. We could make some hefty cloaks outta dese.", sourceObjectiveStatus = "unverified-source-field" }
quests[24762] = { id = 24762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proving Pit", description = "Ya done quite well for ya'self, {class}. I'm sure I could teach ya a trick or two here and dere, but I not be wastin' ya time on tiki targets no longer.\n\nl put one last trial before ya den, mon. Head over to da provin' pit in the middle of dis area and fight a real baddy - one dat wants ta kill ya back. Just let the jailor by the pit know when ya ready.", sourceObjective = "Speak to a Darkspear Jailor, then enter the proving pit and kill a Captive Spitescale Scout.", progress = "All trolls gotta prove demselves before we let them move past da training grounds.", completion = "Ya handle yerself quite well. Ya gonna be quite powerful some day.", sourceObjectiveStatus = "unverified-source-field" }
quests[24763] = { id = 24763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Than Expected", description = "Ya definitely more den expected, mon. I'm sure dere's more important stuff we can be usin' ya talents on now. Ya don't need ta hang out with da newbloods no more.\n\nHead down to da village to da southeast and make yaself known. Lend a hand here and there and I'm sure ya make yer way up to sometin' more prestigious quick enough.", sourceObjective = "Report to Vol'jin at Darkspear Hold.", completion = "Ya tha new recruit everyone's talkin' about, eh? Welcome ta tha Darkspear.", sourceObjectiveStatus = "unverified-source-field" }
quests[24764] = { id = 24764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rise of the Darkspear", description = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here.\n\nVol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream.\n\nNo, dis time we not fleein'. Dis time, we are fightin' for a home dat will last.\n\nIt's time to begin ya trainin', {name}. Speak with Zen'Tabra to the east.", sourceObjective = "Meet with Zen'Tabra in the Darkspear Training Grounds.", completion = "Anotha newblood, eh?\n\nYa actually have a wild look about ya though. Fierce eyes. You might have the makings of a real {class}.\n\nLets not waste anymore time 'den.", sourceObjectiveStatus = "unverified-source-field" }
quests[24765] = { id = 24765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Basics: Hitting Things", description = "Alright, mon. We start simple. I need ta know dat you know the basics of the druidic arts.\n\nGo thrash dose tiki targets. Take it slowly. Natural-like. I'll watch how you form your casts and we'll go from dere.", sourceObjective = "Destroy 6 Tiki Targets.", progress = "Strength isn't da end all of defeating ya enemy, and it most certainly isn't tha end all of stayin' alive. Fightin' is about balance. This'll become more apparent as ya learn animal forms, but it holds true even now. Everytin' has its time and place.", completion = "Not bad, mon. Ya have a natural flow to ya casts - you may have a talent for dis.\n\nSome rough edges ta be sure, but we'll get dose ironed out here and I'll teach ya a few new tings as we go.", sourceObjectiveStatus = "unverified-source-field" }
quests[24766] = { id = 24766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arts of a Druid", description = "As ya grow in powah, ya ability to call on nature gets strongah, too. Ya wanna see?\n\nGo get some experience and show me what ya' learn.", sourceObjective = "Reach level 3 to learn Moonfire. Practice using it on a Tiki target in the Darkspear Training Grounds.", progress = "Veteran druids can take on animal forms, grantin' great speed, tough skin, or even tha ability ta fly.", completion = "Good work, mon! Dis stuff come easy to ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24767] = { id = 24767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rough Start", description = "Lets put dose skills ta use. I'll start ya off easy, mon.\n\nThere be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight.\n\nDey're all over the island. Bring me some cat pelts.", sourceObjective = "Retrieve 6 Wildmane Cat Pelts.", progress = "I doubt dey too much of a challenge, mon, but they'll still claw up ya ankles if ya don't stay quick footed.", completion = "Dese are some fine pelts, boy. We could make some hefty cloaks outta dese.", sourceObjectiveStatus = "unverified-source-field" }
quests[24768] = { id = 24768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proving Pit", description = "Ya done quite well for ya'self, {class}. I'm sure I could teach ya a trick or two here and dere, but I not be wastin' ya time on tiki targets no longer.\n\nl put one last trial before ya den, mon. Head over to da provin' pit in the middle of dis area and fight a real baddy - one dat wants ta kill ya back. Just let the jailor by the pit know when ya ready.", sourceObjective = "Speak to a Darkspear Jailor, then enter the proving pit and kill a Captive Spitescale Scout.", progress = "All trolls gotta prove demselves before we let them move past da training grounds.", completion = "Ya handle yerself quite well. Ya gonna be quite powerful some day.", sourceObjectiveStatus = "unverified-source-field" }
quests[24769] = { id = 24769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Than Expected", description = "Ya definitely more den expected, mon. I'm sure dere's more important stuff we can be usin' ya talents on now. Ya don't need ta hang out with da newbloods no more.\n\nHead down to da village to da southeast and make yaself known. Lend a hand here and there and I'm sure ya make yer way up to sometin' more prestigious quick enough.", sourceObjective = "Report to Vol'jin at Darkspear Hold.", completion = "Ya tha new recruit everyone's talkin' about, eh? Welcome ta tha Darkspear.", sourceObjectiveStatus = "unverified-source-field" }
quests[24770] = { id = 24770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rise of the Darkspear", description = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here.\n\nVol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream.\n\nNo, dis time we not fleein'. Dis time, we are fightin' for a home dat will last.\n\nIt's time to begin ya trainin', {name}. Speak with Legati to the east.", sourceObjective = "Meet with Legati in the Darkspear Training Grounds.", completion = "Anotha newblood, eh?\n\nYa actually have a sly look about ya though. Fierce eyes. You might have the makings of a real {class}.\n\nLets not waste anymore time 'den.", sourceObjectiveStatus = "unverified-source-field" }
quests[24771] = { id = 24771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Basics: Hitting Things", description = "Alright, mon. We start with da basics. I need ta know dat you know how ta swing dose weapons you're totin' around.\n\nGo thrash dose tiki targets. Take it slowly. Natural-like. I'll watch ya fighting form and we'll go from dere.", sourceObjective = "Destroy 6 Tiki Targets.", progress = "Strength isn't da end all of defeating ya enemy, and it most certainly isn't tha end all of stayin' alive. Fightin' is about balance. Everytin has its time and place.", completion = "Not bad, mon. Ya have a natural flow to ya swings - you may have a talent for dis.\n\nSome rough edges ta be sure, but we'll get dose ironed out here and I'll teach ya a few new tings as we go.", sourceObjectiveStatus = "unverified-source-field" }
quests[24772] = { id = 24772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arts of a Rogue", description = "As ya fight ya enemies, ya will learn new tricks you use ta be even bettah'. \n\nThere's one ya should be learnin' soon to let ya see dere weaknesses and set up for devastating combo attacks. After ya've struck a few blows to weaken ya foe, finish dem off with a vicious evisceration attack.\n\nWhen ya learn it, try it out. Let me know when ya tink you have it down.", sourceObjective = "Reach level 3 to learn Eviscerate, then use Eviscerate 3 times against a Tiki Target.", progress = "As ya progress in skill, it will become even harder for people or tings to detect ya.", completion = "Good work, mon! Dis stuff come easy to ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24773] = { id = 24773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rough Start", description = "Lets put dose skills ta use. I'll start ya off easy, mon.\n\nThere be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight.\n\nDey're all over the island. Bring me some cat pelts.", sourceObjective = "Retrieve 6 Wildmane Cat Pelts.", progress = "I doubt dey too much of a challenge, mon, but they'll still claw up ya ankles if ya don't stay quick footed.", completion = "Dese are some fine pelts, boy. We could make some hefty cloaks outta dese.", sourceObjectiveStatus = "unverified-source-field" }
quests[24774] = { id = 24774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proving Pit", description = "Ya done quite well for ya'self, {class}. I'm sure I could teach ya a trick or two here and dere, but I not be wastin' ya time on tiki targets no longer.\n\nl put one last trial before ya den, mon. Head over to da provin' pit in the middle of dis area and fight a real baddy - one dat wants ta kill ya back. Just let the jailor by the pit know when ya ready.", sourceObjective = "Speak to a Darkspear Jailor, then enter the proving pit and kill a Captive Spitescale Scout.", progress = "All trolls gotta prove demselves before we let them move past da training grounds.", completion = "Ya handle yerself quite well. Ya gonna be quite powerful some day.", sourceObjectiveStatus = "unverified-source-field" }
quests[24775] = { id = 24775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Than Expected", description = "Ya definitely more den expected, mon. I'm sure dere's more important stuff we can be usin' ya talents on now. Ya don't need ta hang out with da newbloods no more.\n\nHead down to da village to da southeast and make yaself known. Lend a hand here and there and I'm sure ya make yer way up to sometin' more prestigious quick enough.", sourceObjective = "Report to Vol'jin at Darkspear Hold.", completion = "Ya tha new recruit everyone's talkin' about, eh? Welcome ta tha Darkspear.", sourceObjectiveStatus = "unverified-source-field" }
quests[24776] = { id = 24776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rise of the Darkspear", description = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here.\n\nVol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream.\n\nNo, dis time we not fleein'. Dis time, we are fightin' for a home dat will last.\n\nIt's time to begin ya trainin', {name}. Speak with Ortezza to the east.", sourceObjective = "Meet with Ortezza in the Darkspear Training Grounds.", completion = "Anotha newblood, eh?\n\nYa actually have a wild look about ya though. Fierce eyes. You might have the makings of a real {class}.\n\nLets not waste anymore time 'den.", sourceObjectiveStatus = "unverified-source-field" }
quests[24777] = { id = 24777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Basics: Hitting Things", description = "Alright, mon. We start with da basics. I need ta know dat you know how ta use dat weapon you're totin' around.\n\nGo thrash dose tiki targets. Take it slowly. Natural-like. I'll watch ya fighting form and we'll go from dere.", sourceObjective = "Destroy 6 Tiki Targets.", progress = "Aim isn't da end all of defeating ya enemy, and it most certainly isn't tha end all of stayin' alive. Fightin' is about balance. Everytin has its time and place.", completion = "Not bad, mon. Ya have a natural flow to ya attacks - you may have a talent for dis.\n\nSome rough edges ta be sure, but we'll get dose ironed out here and I'll teach ya a few new tings as we go.", sourceObjectiveStatus = "unverified-source-field" }
quests[24778] = { id = 24778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arts of a Hunter", description = "As ya' start to get da hang of tings, ya gonna figure out how ta do new tricks.\n\nOne of da' first ya gonna learn is to keep a steady hand between shots, or else ya gonna find yaself exhausted and not really managin' to kill much.\n\nGo get some more experience 'till ya figure it out, 'den come back and try it out. Let me know when ya tink you have it down.", sourceObjective = "Reach level 3 to learn Steady Shot. Use Steady Shot 5 times on a Tiki Target.", progress = "No matta how much ya learn or how good ya get, it's the steady hand between ya shots that will keep ya enemies hurtin'. Don't forget to mix dis practice in-between da rest of tha tricks ya learn.", completion = "Good work, mon! Dis stuff come easy to ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24779] = { id = 24779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rough Start", description = "Lets put dose skills ta use. I'll start ya off easy, mon.\n\nThere be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight.\n\nDey're all over the island. Bring me some cat pelts.", sourceObjective = "Retrieve 6 Wildmane Cat Pelts.", progress = "I doubt dey too much of a challenge, mon, but they'll still claw up ya ankles if ya don't stay quick footed.", completion = "Dese are some fine pelts, boy. We could make some hefty cloaks outta dese.", sourceObjectiveStatus = "unverified-source-field" }
