quests[24823] = { id = 24823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Destruction", progress = "You seek to continue down the path of destruction?", completion = "You continue to prove yourself, {name}.  Accept this, not as a gift, but as a tool for the fight against the Scourge." }
quests[24824] = { id = 24824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Disturbed Earth", description = "We are here to monitor the scars of the land, and watch for further signs of instability.  While we haven't seen any yet, a cataclysmic aftershock could devastate the Barrens even further.\n\nTo the northeast, near the chasm, earth elementals rampage out of control. To soothe the earth, these need to occasionally be destroyed, and their essence returned in a ritual. If you help us do this, {class}, I would be happy to reward you.", sourceObjective = "Collect 4 Disturbed Earth Fragments from Disturbed Earth Elementals.", progress = "The elements must be carefully balanced, so returning the essence is key.  I hope you've been collecting it...", completion = "Thank you, friend. It's important we try to calm this earth in every way we can.", sourceObjectiveStatus = "unverified-source-field" }
quests[24825] = { id = 24825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Wisdom", progress = "You seek to continue down the path of wisdom?", completion = "You continue to prove yourself, {name}.  Accept this, not as a gift, but as a tool for the fight against the Scourge." }
