quests[24896] = { id = 24896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Classic Random 65-70 (Nth)" }
quests[24897] = { id = 24897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Back to Town", description = "We were wrong. It wasn't the naga that were preparing to attack... it was the nearby Oomlot tribe.\n\n{name}, you need to get back to the Town-In-A-Box. The pygmies are already attacking!\n\nHere, take this. We bought it off of a pygmy who said it used to belong to some great leader of theirs. Someone whose name translates as Dark Tan Helmet.\n\nIt should fool them so that they don't attack you.", sourceObjective = "Speak with Sassy Hardwrench at the Town-In-A-Box on the Lost Isles.", completion = "{name}? We're saved!\n\nWho am I kidding? We're all going to die!!!", sourceObjectiveStatus = "unverified-source-field" }
quests[24901] = { id = 24901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Town-In-A-Box: Under Attack", description = "{name}, you have to defend us!\n\nI had the eggheads deploy the town's cannon defenses, but it seems like there's an unlimited supply of these Oomlot warriors!\n\nGet your behind into one of those B.C. Eliminators and eliminate the pygmy threat to the town!", sourceObjective = "Use a B.C. Eliminator to defeat 30 Oomlot Warriors.", progress = "That's not enough, hon. Can you take care of more of them?", completion = "Okay, I think that's good enough for now, but they took a bunch of the townsfolk captive.\n\nWe're going to have to take the fight to them!", sourceObjectiveStatus = "unverified-source-field" }
quests[24902] = { id = 24902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunt For Sylvanas", description = "It's true then?  Gilneas has lost her favorite son.\n\nWe will mourn when this is all over but not a day sooner.\n\nWe will not allow ourselves the luxury of grief while the enemy still breathes Gilnean air.\n\nMy father's men are ready to strike while we still have the Banshee Queen's trail.  Just say the word if you're ready.  Liam deserves swift vengeance.", sourceObjective = "Follow Tobias Mistmantle in the Hunt for Sylvanas.", progress = "Did you find her, {name}?", completion = "The Plague?  Something so heinous that not even the orcs condone its use?  I'd say this warrants notifying King Greymane.", sourceObjectiveStatus = "unverified-source-field" }
quests[24903] = { id = 24903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance or Survival", description = "Tell Greymane that we have trackers on Sylvanas and tell him about the Plague.\n\nThe decision will be his.  Launch an all out attack against the leader of the Forsaken or try to evacuate our survivors.", sourceObjective = "Speak to King Genn Greymane at Greymane Court in Gilneas City.", completion = "You present me with the most difficult choice of my life, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24904] = { id = 24904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Gilneas City", description = "The time has come, {name}.  We've rallied and armed every available Gilnean.\n\nIt is time to meet the enemy head on.  Time to settle the score with Sylvanas and her Forsaken dogs once and for all.\n\nLiam is heading the assault from this gate.  King Greymane and my father are leading the assault on the other districts.\n\nYou have a crucial role to play in this as well.  Take this rapier.  Use it to inspire our men and women in combat.  Speak to Krennan Aranas to take part in the battle for Gilneas City.", sourceObjective = "Achieve victory in the Battle for Gilneas City.", progress = "No...", completion = "We've driven the Forsaken back.  We hold three out of the four districts.\n\nBut at what cost...", sourceObjectiveStatus = "unverified-source-field" }
quests[24905] = { id = 24905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Returning a Favor", description = "You know, while you were out doin' your thing, Megs stopped by here. I hadn't seen her in months, but she barely gave me the time of day, just wanted me to tell you she had more business lined up.\n\nShe said she was headed over to the Dunemaul Compound to set up shop, something about ogres. Since you're done here, might as well head over...I wouldn't keep a goblin like her waiting.", sourceObjective = "Find Megs Dreadshredder at the Dunemaul Camp.", completion = "I've got a great one for you this time, {name}. We're gonna initiate these ogres into the Horde...working directly under us.", sourceObjectiveStatus = "unverified-source-field" }
quests[24906] = { id = 24906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seaside Salvage", description = "We've got to get goods moving in this market ASAP if we want to be competitive. I've got an angle for us.\n\nGadgetzan's under blockade by pirates, but plenty of the goods that get blown off the ships survive intact... they just wash away. Most of them wash up in the shallows just south of town.\n\nHead down there and start salvaging; there's crates full of pure profit just floating around down there.", sourceObjective = "Collect 7 Steamwheedle Supplies.", progress = "Let's see what you've got.", completion = "Hmm, mostly usable. This is good stuff. I've already got buyers lined up, of course.\n\nHere's your advance for the rest of the work you're gonna do for me and the Bilgewater Cartel...partner.", sourceObjectiveStatus = "unverified-source-field" }
quests[24907] = { id = 24907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Puddle Stomping", description = "Here's the situation. If we want to establish the Bilgewater Cartel's market presence in Gadgetzan, we'll need to start providing services to the community.\n\nThe new coast has been great for business here, but the sea also brought sea giants with it. They're large, foul, and drive real estate values down.\n\nHead to the shallows just south of town and kill as many as you can, and I'll cut you in on some of the deals I'm brokering here.", sourceObjective = "Kill 8 Tidal Striders.", completion = "Property values have already gone up since you left. People like seafront views that don't include briny, gnarled giants stomping around.\n\nHere's your cut, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24910] = { id = 24910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rocket Rescue", description = "Alright, {name}. We've done enough small jobs around here; it's time to seal the deal.\n\nThe ruins of Steamwheedle Port are still full of hapless Steamwheedle goblins, waiting to be rescued. Every single one of them is a potential future customer. They're firing on every boat that leaves port...so I say we take to the skies!\n\nThere's a hot air balloon just outside of town near the docks, we can use that. Go ahead and hop in, I'll catch up with you.", sourceObjective = "Deliver Life-Rockets to 5 Steamwheedle Survivors and use bombs to kill 40 Southshore Blockaders.", progress = "What's with the premature bail-out? We gotta get back out there.", completion = "Isn't it nice when you can do a good deed, and see enormous future financial gains from it? It warms my little goblin heart. And my big goblin wallet.\n\nYou did great, kid. Gadgetzan's gonna be ours soon. Here's a little token of my appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[24911] = { id = 24911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tropical Paradise Beckons", description = "Hey, you look like a discriminating adventurer.  Are you looking for something different?  Something exotic?  Something... profitable?\n\nWell shake the sand out of your boots, because I've got a proposition for you.  Williden Marshal is looking for competent sellswords such as yourself.  He's set up camp at Marshal's Stand, just southeast of the volcano in the center of lush Un'Goro Crater.\n\nThen again, paradise isn't for everyone, {race}.  It's up to you.  Your tropical oasis awaits.", sourceObjective = "Report to Williden Marshal at Marshal's Stand in Un'Goro Crater.", completion = "Hey Hol'anyee, look at the getup on this one!\n\n<Williden turns to face you.>\n\nAhem.  Our recruiter sent you?  Good.  Let's start out with a bit of honesty: Un'Goro isn't the perfect nirvana that you may have been promised.  You've probably figured that out on the way over here, though.\n\nShall we get to work?", sourceObjectiveStatus = "unverified-source-field" }
quests[24912] = { id = 24912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Empowerment", progress = "<Highlord Darion Mograine speaks to you purposefully.>\n\nShadow's Edge is prepared to receive its final endowment of power.\n\nThe time has come to attempt the forging of Shadowmourne!", completion = "Stand Clear, {class}, and steady yourself." }
quests[24913] = { id = 24913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remember the Light", description = "Magtoor grows weaker by the second, {name}. My remedy is prepared... it must work. It must!\n\nYou have done so much for the both of us. I would be honored if you stayed for what may be Magtoor's final moments.", sourceObjective = "Help Anchorite Avuun say farewell to Magtoor.", completion = "I am moved, {name}. Prophet Velen has been in closely guarded seclusion. He has dared not waste his energy on anything save preparing for the final confrontation he has foretold.\n\nAnd yet, he came here, in person, to comfort a single dying soul.\n\nI must thank you as well, for helping me make my last effort to comfort my friend. My research will continue... and I hope that Magtoor will continue to watch over me.", sourceObjectiveStatus = "unverified-source-field" }
quests[24914] = { id = 24914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Personal Property", description = "You can detect no hinges or openings on this box. Were it not for the shifting of items inside, it could easily be mistaken for solid metal.\n\nIf anyone could know the method of its opening, it would be Highlord Mograine.", sourceObjective = "Bring the Sealed Chest to Highlord Darion Mograine in Icecrown Citadel.\n\nProvided item:", completion = "<After tracing a complex pattern of runes on each of the box's surfaces, the outline of a lid appears and a click echoes through the chamber.>\n\nHere you are, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24915] = { id = 24915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mograine's Reunion", progress = "What is that you hold, {class}?\n\nIt calls out to me, stirring feelings I thought to be long dead.", completion = "Impossible...\n\nFather, is it you?!\n\nYou have done me a great service, hero. I offer you the reins of my faithful steed. Do with it as you please, but do not forget those that assisted you in this monumental feat." }
quests[24916] = { id = 24916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jaina's Locket", progress = "Yes, {class}? How can I assist you?", completion = "What... how did you manage to come by this!?\n\nYou have done me a great service, hero. My heart could not bear to keep this locket, but I will place an enchantment upon it that you may find useful. Do with it as you please, but do not forget those that assisted you in this monumental feat." }
quests[24917] = { id = 24917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muradin's Lament", progress = "Whatdya got there, {race}?", completion = "Aye. I know this blade... and I will treasure it always - a moment of time that will be lost forever.\n\nYou have done me a great service, hero. I offer you a gift from the Frostborn dwarves. Do with it as you please, but do not forget those that assisted you in this monumental feat." }
quests[24918] = { id = 24918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sylvanas' Vengeance", progress = "What is it, {race}?", completion = "<Sylvanas silently reflects for a moment before returning her gaze to you.>\n\nYou have done me a great service, hero. I offer you the boon of the Banshee Queen. Do with it as you please, but do not forget those that assisted you in this monumental feat." }
quests[24919] = { id = 24919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lightbringer's Redemption", progress = "How may I be of service, {race}?", completion = "<Uther stares at the medal, speechless for a moment.>\n\nArthas' medal.\n\nI remember well the day I presented it to him...\n\nYou have done me a great service, hero. My soul may now rest in peace. I offer you a memory lost in time. Do with it as you please, but do not forget those that assisted you in this monumental feat." }
quests[24920] = { id = 24920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slowing the Inevitable", description = "As much as I want to exact swift and brutal revenge... I must honor my son's memory first.  He cared for his people first and foremost.\n\nThe Undertaker's Pass goes underground below Northgate River.  You must prevent the plague from being deployed while we evacuate our men, women and children to Aderic's Repose.\n\nWe captured one of the Forsaken's dreaded bombing bats.  I want you to fly the infernal beast as best you can and unleash hell upon those who seek to bring the Plague to our people.  Hurry!", sourceObjective = "Use the Captured Riding Bat to destroy 6 Forsaken Catapults and 40 Invading Forsaken.", progress = "Is it done, {name}?", completion = "You've done well, {name}.  Almost everybody managed to make it through.", sourceObjectiveStatus = "unverified-source-field" }
quests[24921] = { id = 24921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Aubrey", description = "You there! Fresh off the boat? Welcome to Kalimdor, a land hellbent to kill you or die tryin'.\n\nThere's trouble at the hold - as I'm sure you noticed on your way in. Admiral Aubrey needs all hands on deck if we're to make it through this. Consider yourself drafted, {class}!\n\nFollow the road up the hill and you'll find Aubrey in the tower, topside.", sourceObjective = "Report to Admiral Aubrey in Northwatch Hold.", completion = "Hm? What unit are you with, {class}?\n\nNo matter, we need all hands. My fleet is in tatters and they've broken into the hold. You armed? That's good enough for me.", sourceObjectiveStatus = "unverified-source-field" }
quests[24922] = { id = 24922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Classic Random Heroic (1st)" }
quests[24923] = { id = 24923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Crusade Random Heroic (Nth)" }
quests[24924] = { id = 24924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oomlot Village", description = "The pygmies took most of our people back to their village. Who knows what evil they're up to?\n\n{name}, you have to go up there and free all of the captives before the pygmies work their voodoo on them!\n\nIzzy's already up near Oomlot Village to the southeast. She'll give you the heads-up on what's going down.\n\nYour pygmy helmet looks like it's in bad shape, but it should last long enough for you to get there.\n\nI hope.", sourceObjective = "Speak with Izzy at Oomlot Village on the Lost Isles.", completion = "{name}? What are you doing wearing that pygmy helm? Looks like it's about to fall apart.\n\nI'm glad that they sent you up here. I thought for sure they were going to send that jerk, Grapplehammer and his ego-enabling assistant.", sourceObjectiveStatus = "unverified-source-field" }
quests[24925] = { id = 24925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free the Captives", description = "They've got a bunch of our people in there. I know that they're doing strange rituals to them. It looks like they're sucking the life force right out of them!\n\nYou have to go into the village and free the captives before it's too late!", sourceObjective = "Free 5 Goblin Captives.", completion = "Great job, but that's not even half of the hostages that they took from town.\n\nDarn it all! They must have taken the rest of the captives to their other villages up in the volcano!", sourceObjectiveStatus = "unverified-source-field" }
quests[24926] = { id = 24926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Serving A-Me 01", description = "Greetings.  I unit A-Me 01.  You... {race}?\n\nA-Me's mission to study the local gorillas was success.  A-Me has gathered data that Karna needs.\n\nA-Me 01 not returning, though.  A-Me has new family now.  Here, with the gorillas, A-Me stay.\n\n<A-Me 01 detaches a small device from her hand and gives it to you.>\n\nYou bring data back to Karna.  You tell her what happen.", sourceObjective = "Bring A-Me's Thumb Drive back to Karna Remtravel at Mossy Pile in Un'Goro Crater.", progress = "Wh... what's this?", completion = "She decided to stay?  Fascinating... I'll have to look over this data and find out why.\n\nThank you again, {name}. I really appreciate it.", sourceObjectiveStatus = "unverified-source-field" }
quests[24927] = { id = 24927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dead Man's Chest", description = "Look, babe, you should be able to see what's happening here pretty easily. There's pirates, there's goblins, the goblins are fighting the pirates. There's some sad little gnomes trying to fight the pirates too.\n\nI'll make it nice and simple for you: we need to kill a lot of pirates. Go do that, 'kay? We don't want the gnomes killing more than us, after all.", sourceObjective = "Kill 15 Southsea Freebooters of any kind.", progress = "Look, if you think the bare minimum is enough, then ok. But some people choose to kill more pirates and I encourage that, ok?\n\nAnd by \"ok\", I mean \"go kill more and stop wasting my time\".", completion = "I'm pleased to report that our brand recognition in this area has skyrocketed now that you've killed most of the people who didn't want us here.", sourceObjectiveStatus = "unverified-source-field" }
quests[24928] = { id = 24928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To The Ground!", description = "I've conducted a thorough appraisal of the real estate here and, unfortunately, its market value is just far too low to be of any use. We're going to have to renovate.\n\nLuckily for you, I've learned a few things about arson. Hopefully you have too! You're going to be throwing these perfectly safe bottles of flaming rum at those filthy ramshackle huts over there.\n\nTry not to stand downwind.", sourceObjective = "Set fire to the Northwest Shack, the Southeast Shack, and the Northeast Shack.", completion = "Wonderful job. Have you ever thought about becoming a full-time arsonist? I know a few people, it's a nice gig.\n\nWell, we'll chit-chat about that one later. More to do here!", sourceObjectiveStatus = "unverified-source-field" }
quests[24929] = { id = 24929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Send a Message", description = "The Oomlot leader, Yngwie, is too powerful to be left alive. He's barking nonsense from the raised west side of the village, across the rope bridge.\n\nGo up there and get him before he sends the rest of the village against us.\n\nPiece of cake!", sourceObjective = "Slay Yngwie.", completion = "Nice work, bud! Hope he wasn't too tough.", sourceObjectiveStatus = "unverified-source-field" }
quests[24930] = { id = 24930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "While You're At It", description = "Fine by me if King Greymane wants you to risk your life to rescue a known traitor.\n\nDo me a favor and do something useful while you're out there and kill these cursed fleabags.", sourceObjective = "Kill 5 Bloodfang Worgen.", progress = "What is it then, {name}?", completion = "If I hadn't seen you kill a few of the mangy things with my own eyes, I'd think you did not complete the task I asked of you.\n\nIt looks like we're hardly putting a dent in their numbers.", sourceObjectiveStatus = "unverified-source-field" }
quests[24931] = { id = 24931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gazer Tag", description = "You're going out to hunt hyenas, eh? If you don't mind, I've got an offer myself. I'm in need of eyes from the Glasshide Gazers that lurk to the north. Their eyes contain wonderful crystals, valuable to...collectors.\n\nNow, you may have heard that some sad individuals use these to enhance paramental abilities, but I assure you, my interests are purely academic!\n\nBring me a good portion of them and I'll pay you well for them. Better than these copper-pinching goblins will, at least!", sourceObjective = "Collect 5 Ocular Crystals from Glasshide Gazers.", progress = "Do, ah, do you have them?", completion = "Ahh, perfect! Just what I need...full of potent focusing energies...\n\n...ahem! I mean, perfect for my collection! Narain Soothfancy is in no need of artificial enhancement of any kind!\n\nNow take your pay and be off!", sourceObjectiveStatus = "unverified-source-field" }
quests[24932] = { id = 24932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cutting Losses", description = "I've spent the last week starin' at this ugly pit trying to think of how to exploit a bunch of dangerous, violent arthropods for profit. Now I'm out of ideas, and starving.\n\nThese things are a wash, and I say it's time to start clearing them out. Head down into that pit and start killin' bugs.", sourceObjective = "Kill 15 Hazzali Silithid of any kind in the Gaping Chasm.", completion = "This isn't goin' fast enough. There's gotta be a faster way...", sourceObjectiveStatus = "unverified-source-field" }
quests[24933] = { id = 24933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chicken of the Desert", description = "I've got an idea, but we're going to need bait.\n\nThe other day I saw a rabid blisterpaw hyena wander too close to the edge of the chasm, and one of the silithid comes diving out of nowhere. Nearly swallowed it whole! Horrible sight.\n\nSo we're gonna need hyena meat, obviously. Go gather some, make sure it's fresh, and bring it back here. There should be plenty just north of the camp.", sourceObjective = "Collect 6 pieces of Hyena Meat.", progress = "This is fresh, right? They won't go after anything that's been withering in the sun.", completion = "Man, this stuff looks delicious. I'm half tempted to just fry some up myself.\n\nNo! We've gotta focus on gettin' out of here.\n\nMaybe just one piece...", sourceObjectiveStatus = "unverified-source-field" }
quests[24934] = { id = 24934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repel Boarders!", description = "{name}, the sea is our only lifeline, and right now most of my fleet is either steaming back to Theramore for repairs or rusting at the bottom of this bay. Only the Blackpool remains afloat to defend our harbor.\n\nBut she's just signaled that she's being boarded!\n\nSpeak to me when you're ready, I'll have one of our naval gryphons deposit you right on the deck. Slaughter the rageroar sea dogs who dare assault my precious ship and report to Captain Fisher for further orders.", sourceObjective = "Speak to Admiral Aubrey to fly to the Blackpool and kill 6 Rageroar Sea Dogs.", progress = "Blood! All over my freshly polished brass.", completion = "You make a hell of a marine, {name}.\n\nWe'll mop up the others. But it looks like the Horde fleet is disengaging - maybe to land more troops ashore?\n\nAdmiral Aubrey will know what to do. Talk to me when you're ready to fly back!", sourceObjectiveStatus = "unverified-source-field" }
quests[24937] = { id = 24937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oomlot Dealt With", description = "{name}, you have to get back to the Town-In-A-Box and warn them about the goblin zombies up in the volcano's caldera!", sourceObjective = "Speak with Sassy Hardwrench at the Town-In-A-Box on the Lost Isles.", completion = "They turned some of our people into zombies? Tell me something I don't know....", sourceObjectiveStatus = "unverified-source-field" }
quests[24938] = { id = 24938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Guns of Northwatch", description = "Captain Fisher signaled us from below. The Horde fleet is landing shore parties? We can't let them flank us from the beach.\n\nI've already sent two of my best gunners down there to defend the beach head. Talk to Cannoneer Smythe down on the shore.\n\nYou'll have to fight your way through the courtyard to get there. See if you can help the others secure the hold on your way down!", sourceObjective = "Speak with Cannoneer Smythe.", completion = "Aubrey sent you? Good! I take it you know your way around a cannon?", sourceObjectiveStatus = "unverified-source-field" }
quests[24939] = { id = 24939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Run Out the Guns", description = "We've got the hardware but not the manpower, {name}. Man one of the carronades on the shore here and take out those incoming boats!", sourceObjective = "Use a Northwatch Shore Battery to destroy 10 Rageroar Rowboats.", completion = "Ho ho! The beach is ours!\n\nWe just might keep a foothold on this miserable dustball of a continent after all.", sourceObjectiveStatus = "unverified-source-field" }
quests[24940] = { id = 24940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Up the Volcano", description = "A whole bunch of our people headed up to the top of the volcano to mount a counter-offensive. There's something horrible brewing up there on the Lost Peak.\n\nThey're waiting for you before they make any moves against the pygmies. Those evil little things turned a lot of us into zombies!\n\n{name}, save us!", sourceObjective = "Speak with Coach Crosscheck at the Lost Peak on the Lost Isles.", completion = "My star player has arrived!", sourceObjectiveStatus = "unverified-source-field" }
quests[24941] = { id = 24941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Langridge Shot", description = "{class}! Thank the light - they've practically driven us back to the docks. The courtyard is overrun!\n\nWe're out of canister shot and the orcs are getting ready for an assault up the hill. We need to improvise some scatter-shot, and fast.\n\nHurry, run into the broken tower here and grab whatever sharp, pointy bits of scrap metal you can lay your hands on. Knives, forks, nails - anything! Load the cannon when you've got an armful!", sourceObjective = "Gather 15 pieces of Langridge Shot.", progress = "Paxton has already loaded a charge into the cannon. All it needs is the ammunition you improvised.", completion = "The Horde is massing at the base of the hill. Breathlessly, you stuff the debris you collected into the muzzle of the cannon, step back, cover one ear, and tug on the igniter cord...", sourceObjectiveStatus = "unverified-source-field" }
quests[24942] = { id = 24942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zombies vs. Super Booster Rocket Boots", description = "Those zombies that got past us are nothing compared to the numbers waiting just through the pass. If we don't deal with them soon, the pygmy witch doctors are going to send all of them against the town, and even the cannons down there won't be able to handle that many!\n\nI brought a couple of shredder boots along. Greely modded them and now they're Super Booster Rocket Boots!\n\nUse the boots to incinerate the zombies in the Oostan villages to the east.", sourceObjective = "Use the Super Booster Rocket Boots to slay 50 Goblin Zombies.", progress = "You still have a few {race} zombies to deal with, {name}. Look sharp, superstar!", completion = "You did it! No more zombies to worry about. Let's pause a moment in silence for the stinky departed.\n\nOkay, done.", sourceObjectiveStatus = "unverified-source-field" }
quests[24943] = { id = 24943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Re-Take the Courtyard", description = "That's one way to clear a hill. Those corpses are impaled with knives and forks!\n\nThe Rageroar clan has breached the walls, but we can still turn this fight around. Go down the hill and help our men hold on to the courtyard below...", sourceObjective = "Kill 10 Rageroar Grunts.", completion = "Great work! We've knocked them on their heels, maybe long enough to shore up our defenses.\n\nProvided we find a way to take out their artillery...", sourceObjectiveStatus = "unverified-source-field" }
quests[24944] = { id = 24944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back in the Fight", description = "This fight isn't over, {class}. Not by a long shot.\n\nSome of the soldiers in the courtyard still have breath in their lungs. We can save them! I've soaked these rags in an herbal remedy we used to rely on back in Gilneas. The smell is awful but this poultice can practically raise the dead.\n\nUse these bandages on wounded defenders down in the courtyard and we'll see if we can't get them back in the fight.", sourceObjective = "Use the Herb-Soaked Bandages on 6 Wounded Defenders.", progress = "I hope you have enough bandages. My supply of those herbs was cut off when these brutes sacked my beloved Gilneas.", completion = "A steady stream of the walking wounded have come up the hill to see me, {name}. I trust that was your work? Well done!", sourceObjectiveStatus = "unverified-source-field" }
quests[24945] = { id = 24945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Three Little Pygmies", description = "Look, I think it's great that we're destroying all of these zombies, even though they're our friends and family. But don't you think we should be taking care of the pygmies that are creating them as well?\n\nAt the three Oostan villages, Nord, Sor, and Ost, there are witch doctors: Gaahl, Malmo, and Teloch.\n\nMaybe you could take care of them? I don't want to be turned into a zombie!", sourceObjective = "Slay Gaahl, Malmo, and Teloch.", progress = "Um, boss, look, I don't know how to say this, but you might have missed one or two of those pygmy witch doctors.\n\nI'm just saying.", completion = "I gotta tell you, that's a load off of my mind. That is, I won't have to worry about no new zombies coming after my brains!", sourceObjectiveStatus = "unverified-source-field" }
quests[24946] = { id = 24946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rockin' Powder", description = "I'll give these pygmies one thing... they sure know how to party! But they're not so clever. I think I've discovered the source of their rockin' powers: Rockin' Powder!\n\nIt turns out that this stuff, which turns them into world-class rockers, is also highly explosive. We must have it!\n\nSo, while you're in there at Oostan to the east, make sure that you pickup a whole bunch of the stuff. Trust me, you're going to need it for what's coming up!", sourceObjective = "Collect 5 scoops of Rockin' Powder.", progress = "Hmm, let me see how much you've got.", completion = "This will do. In fact, it's more than we need. I devised an ingenious idea for a weapon that the boots will be turned into once you get them to Hobart.\n\nHand the powder over and I'll load it into the Super Booster Rocket Boots.", sourceObjectiveStatus = "unverified-source-field" }
quests[24947] = { id = 24947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Momentum", description = "We can't just rest on our laurels here, babe. We've got to keep this momentum going! People are talking about us.\n\nUnfortunately, they're also talking about this air-headed gnome, Kelsey, who's apparently been running jobs right alongside us. If we're going to drive her out of what's rightfully a goblin town, we need to seal the deal here.\n\nWe're going to take care of Gadgetzan's pirate problem for them, for good. Head south to Lost Rigger Cove, I'll meet you there.", sourceObjective = "Meet Megs Dreadshredder at Lost Rigger Cove.", completion = "Good thing you're here! I'm gonna need a lot of help if we want to beat these gnomes to the punch.", sourceObjectiveStatus = "unverified-source-field" }
quests[24948] = { id = 24948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lifting the Siege", description = "We'll never be able to re-secure the fortress walls so long as Rageroar and his goons have access to artillery. I need you to fight your way across that chasm and take out his big guns.\n\nOrcs season their heavy machinery with coal tar, which makes them flammable. Take my torch and burn any catapults you see north of Northwatch.\n\nThen, torch those big blade-throwers in Rageroar's base camp! Those things have killed enough of our men.", sourceObjective = "Use Paxton's Torch to burn 3 Rageroar Catapults and 1 Rageroar Blade Thrower.", progress = "Burn it all, {class}. Burn it to cinders!", completion = "Good! Without heavy equipment, the Horde will have to pull back to regroup. We've bought ourselves some time to re-secure the fortress. Well done!", sourceObjectiveStatus = "unverified-source-field" }
quests[24949] = { id = 24949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Booty Duty", description = "Let's not be wasteful here, babe. These pirates have tons of valuable nonsense just sitting around, waiting to be fenced. Can you believe they just sit on this stuff?\n\nI mean, why do they even bother taking it if it's just going to sit around? Stolen goods should be sold off and used to buy shiny new things.\n\nAnyway, be a dear and go grab as much of their loot as you can carry while you're out busting heads. Ciao!", sourceObjective = "Collect 10 pieces of Pirate Booty.", progress = "Let's see what you've got. You're not hiding any for yourself, are you? You'll never find a buyer without me, you know.", completion = "Beautiful! And to think these idiots were just sitting on it.\n\nHere's a bit up front, we'll talk about profit-sharing bonuses later.", sourceObjectiveStatus = "unverified-source-field" }
quests[24950] = { id = 24950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain Dreadbeard", description = "Alright, babe, I've got something bigger for you to take on here.\n\nWe spotted the captain of the Southsea over on one of his boats to the south; that's to the south, and NOT the one we've been suicidally bum-rushing for the better part of several hours. He's sitting up there, smug and stoic, watching us war down here.\n\nI'll spare you the \"hostile takeover\" jokes. Get on his ship and beat the tar out of him, and we're done here!", sourceObjective = "Kill Captain Dreadbeard.", completion = "Sea giants? You think he was training them towards Gadgetzan on purpose?\n\nWhatever, he's splitsville now. And Gadgetzan owes us big time! I can't wait to see the look on Marin's face.\n\nHere's your cut, babe. You're moving up in the world.", sourceObjectiveStatus = "unverified-source-field" }
quests[24951] = { id = 24951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Great Idea", description = "Now that we've got a good pile of fresh chunks, we just tie it to this rope...and now you're ready to go catch me a silithid.\n\nWhat? Don't give me that look, it's perfectly safe. Well, mostly safe. Okay, you might die painfully. But it'll be easy! Just throw this meat out there, wait for a bug to pounce on it, and then drag 'em back here by the rope!\n\nGo after one of the swarmers. I haven't seen the other ones go for hyenas before, and you should find plenty of swarmers around the edge of the pit.", sourceObjective = "Use the Bootlegger Bug Bait to capture a Hazzali Swarmer.", progress = "I don't see any bug with you, pal.", completion = "Look at the size of it! It's glorious. This ugly sucker's gonna help us bring down the whole hive.", sourceObjectiveStatus = "unverified-source-field" }
quests[24952] = { id = 24952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rocket Boot Boost", description = "You need to get those boots down into the caldera to Hobart Grapplehammer.\n\nNow that they're infused with the leftover rockin' powder, they should have enough thrust to get you all the way there on one shot.\n\nWhen you're ready, activate the boots. Don't worry, they're automatically set to land you safely.\n\nI think.", sourceObjective = "Use the Rockin' Powder Infused Rocket Boots and deliver them to Hobart Grapplehammer.", progress = "Well there you are!", completion = "There's no time to waste, boy!\n\nWhat's wrong with the actuator on the left boot?!", sourceObjectiveStatus = "unverified-source-field" }
quests[24953] = { id = 24953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Trying to Kill Some Bugs", description = "Now it's time for my plan to go into full effect. We've got the captured bug strapped up with as many explosives as it can carry, and with Soothfancy's mostly amazing mental powers, we're gonna drive that sucker straight down into the center of the underground hive.\n\nAnd then...BOOM! No more bugs!\n\nYou get the personal honor of directin' the ugly thing. Go talk to Narain and get set up with your bug-pal.", sourceObjective = "Talk to Narain Soothfancy to pilot the Mind-Controlled Swarmer into the Gaping Chasm hive.", progress = "I didn't hear no cave-ins, pal! Try again!", completion = "Oh man, that was awesome! You should've seen the flames coming out of the hive!\n\nHere's your reward, for entertaining me as much as for clearing the hive!", sourceObjectiveStatus = "unverified-source-field" }
quests[24954] = { id = 24954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Children of a Turtle God", description = "Volcanoth is the turtle god in the cave that these primitives worship.\n\nIt's not really a god.\n\n<Hobart rolls his eyes.>\n\nBut it is tough enough that I'm going to have to devise a new weapon for you from the one functioning boot we have left.\n\nI think that the age-old motto of \"fight fire with fire\" applies here. Plus, I like fire!\n\nLet's get some fire glands from Volcanoth's children. That should give me time to modify the rocket boot into something more fitting.", sourceObjective = "Collect 5 Fire Glands.", progress = "No time like the present to be done with the simple task I put before you, {name}. Wouldn't you agree?", completion = "Careful with those glands, {name}, careful!\n\n\n\nAnd now to load them into the refashioned shredder boot. I'm certain that you'll be surprised and amazed by my genius invention.", sourceObjectiveStatus = "unverified-source-field" }
quests[24955] = { id = 24955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Un-Chartered", description = "As I may have mentioned, I'm trying to get these Dunemaul ogres to join the Horde..and  work for the Bilgewater Cartel as cheap local labor.\n\nTo pull this off, we've gotta pay lip service to the actual initiation process and all that, or I'm going to catch flak later on. So I've gotten this charter drawn up, and slapped the initiation rites onto our own limited time offer labor stipulation contract.\n\nI've got a disguise for you here, so suit up and get all these signatures filled out.", sourceObjective = "Obtain 10 Charter Signatures from Dunemaul Ogres.", completion = "Wow, nice work! I'm amazed you even got them to hold a pen without eating it.\n\nYou can uh, just throw the suit over there. Away from me. In the fire.", sourceObjectiveStatus = "unverified-source-field" }
